package i18n

func init() {
	ptBR["Power %s failed: %v — the machine may not shut down; power it off manually.\n"] = "Falha ao executar %s: %v — a máquina pode não desligar; desligue-a manualmente.\n"
	ptBR["This recovery media (v%s) is older than the server requires (v%s); download the current ISO.\n"] = "Esta mídia de recuperação (v%s) é anterior à versão exigida pelo servidor (v%s); baixe a ISO atual.\n"
	ptBR["Recovery cannot proceed: %s\n"] = "A recuperação não pode continuar: %s\n"
	ptBR["Disk %s already contains a Windows installation. Everything on it will be erased.\n"] = "O disco %s já contém uma instalação do Windows. Todo o seu conteúdo será apagado.\n"
	ptBR["Type OVERWRITE to erase it, or press Enter for other options: "] = "Digite OVERWRITE para apagá-lo ou pressione Enter para outras opções: "
	ptBR["Recovery cannot proceed: disk %s already contains a Windows installation. "] = "A recuperação não pode continuar: o disco %s já contém uma instalação do Windows. "
	ptBR["Recovery failed: %s\n"] = "Falha na recuperação: %s\n"
	ptBR["Restored. Rebooting in 10 s (press any key to stay).\n"] = "Restauração concluída. Reiniciando em 10 s (pressione qualquer tecla para permanecer).\n"
	ptBR["Reboot cancelled. Press [r]eboot or [p]oweroff when ready.\n"] = "Reinicialização cancelada. Digite [r] para reiniciar ou [p] para desligar quando estiver pronto.\n"
	ptBR["progress %s not recorded: %v\n"] = "Progresso %s não registrado: %v\n"
	ptBR["A server URL is required.\n"] = "É necessário informar a URL do servidor.\n"
	ptBR["Server URL must start with https://.\n"] = "A URL do servidor deve começar com https://.\n"
	ptBR["Recovery code: "] = "Código de recuperação: "
	ptBR["A recovery code is required.\n"] = "É necessário informar um código de recuperação.\n"
	ptBR["Could not reach %s: %s.\n"] = "Não foi possível acessar %s: %s.\n"
	ptBR["The recovery code was not sent and this did not count as a failed attempt. Check the server URL and the network connection.\n"] = "O código de recuperação não foi enviado e isso não contou como tentativa malsucedida. Verifique a URL do servidor e a conexão de rede.\n"
	ptBR["%s returned a gateway/server error page (HTTP %d%s): the Breeze server may be down or restarting, or the URL may be wrong.\n"] = "%s retornou uma página de erro do gateway/servidor (HTTP %d%s): o servidor Breeze pode estar indisponível ou reiniciando, ou a URL pode estar incorreta.\n"
	ptBR["%s answered, but not as a Breeze recovery server (HTTP %d%s).\n"] = "%s respondeu, mas não como servidor de recuperação Breeze (HTTP %d%s).\n"
	ptBR["The recovery code was not used and this did not count as a failed attempt. Check the server URL.\n"] = "O código de recuperação não foi utilizado e isso não contou como tentativa malsucedida. Verifique a URL do servidor.\n"
	ptBR["The server could not check that code: %v\n"] = "O servidor não conseguiu verificar o código: %v\n"
	ptBR["This did not count as a failed attempt. The server keeps failing; check the server URL, or try again later.\n"] = "Isso não contou como tentativa malsucedida. O servidor continua falhando; verifique a URL ou tente novamente mais tarde.\n"
	ptBR["This did not count as a failed attempt. Try the code again.\n"] = "Isso não contou como tentativa malsucedida. Tente o código novamente.\n"
	ptBR["That code did not work: %v\n"] = "O código não funcionou: %v\n"
	ptBR["Multiple candidate disks found:\n"] = "Vários discos candidatos encontrados:\n"
	ptBR["Select target disk number: "] = "Selecione o número do disco de destino: "
	ptBR["Invalid selection.\n"] = "Seleção inválida.\n"
	ptBR["That does not match. Try again.\n"] = "O valor não corresponde. Tente novamente.\n"
	ptBR["[r]etry  [s]hell  [p]oweroff: "] = "[r] tentar novamente  [s] shell  [p] desligar: "
	ptBR["No shell available on this build.\n"] = "Nenhum shell disponível nesta versão.\n"
	ptBR["Please choose r, s, or p.\n"] = "Escolha r, s ou p.\n"
	ptBR["Target disk: %s  %s  serial %s  %s\n"] = "Disco de destino: %s  %s  série %s  %s\n"
	ptBR["Source disk: %s  %s\n"] = "Disco de origem: %s  %s\n"
	ptBR["Breeze server URL: "] = "URL do servidor Breeze: "
	ptBR["Breeze server URL [%s]: "] = "URL do servidor Breeze [%s]: "
	ptBR["Breeze server URL [%s — from boot cmdline, unverified; confirm or type a different URL]: "] = "URL do servidor Breeze [%s — da linha de comando de inicialização, não verificada; confirme ou digite outra URL]: "
	ptBR["Type the disk serial (%s) to confirm, or 'cancel': "] = "Digite o número de série do disco (%s) para confirmar ou 'cancel': "
	ptBR["This disk reports no serial. Type ERASE to confirm, or 'cancel': "] = "Este disco não informa número de série. Digite ERASE para confirmar ou 'cancel': "
	ptBR["WARNING: the boot cmdline suggests a different server (%s) than the one baked into this recovery media (%s). "] = "AVISO: a linha de comando de inicialização sugere um servidor (%s) diferente do configurado nesta mídia de recuperação (%s). "
	ptBR["Using the media's own server unless you type a different URL below.\n"] = "O servidor da mídia será usado, a menos que você digite outra URL abaixo.\n"
	ptBR[" is viewing your screen"] = " está visualizando sua tela"
}
